// Offline-first service worker. The precache list and cache version live in
// sw-precache.js, regenerated by tools/gen_sw.py (locally or in CI) whenever
// app files change. gen_sw.py also writes the version into the line below,
// so this file changes with every build: an iPhone ignored a change of the
// imported sw-precache.js alone and kept an old build. Do not drop the ?v=.
importScripts("./sw-precache.js?v=b249aa5e08bd-6ebf48c2260d");

const CACHE = "vrtti-" + self.__PRECACHE.version;
// Spellcheck WASM + Czech dictionary (~12.1 MB on the wire) live in their own
// content-addressed cache so app-only deploys keep offline spellcheck intact
// without re-downloading unchanged dictionaries on every release (C4).
const SPELL_CACHE = "vrtti-spell-" + self.__PRECACHE.spellVersion;

// The ~4,000 Twemoji SVGs are not precached (tools/gen_sw.py skips them); they
// are cached one by one on first use. Their cache name is deliberately fixed
// and separate from CACHE: the activate handler deletes every other cache on
// each new build, and an emoji SVG never changes, so re-downloading the set
// after every deploy would be waste.
const EMOJI_CACHE = "vrtti-emoji";
const EMOJI_PATH = "/vendor/twemoji/";

async function ensureSpellPrecache() {
  const urls = self.__PRECACHE.spell || [];
  if (urls.length === 0) return;
  const cache = await caches.open(SPELL_CACHE);
  const missing = [];
  for (const url of urls) {
    if (!(await cache.match(url))) missing.push(url);
  }
  if (missing.length > 0) await cache.addAll(missing);
}

self.addEventListener("install", (event) => {
  const appUrls = self.__PRECACHE.app || self.__PRECACHE.files || [];
  event.waitUntil(
    Promise.all([
      caches.open(CACHE).then((cache) => cache.addAll(appUrls)),
      ensureSpellPrecache(),
    ]).then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((k) => k !== CACHE && k !== SPELL_CACHE && k !== EMOJI_CACHE)
            .map((k) => caches.delete(k))
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  // Both early returns hand the request straight to the network, and both are
  // load-bearing for sync (architecture.md §13.6): the API lives on another
  // origin, its pushes are POST and DELETE, and a cached /api/changes page
  // would replay the same rows for ever. Never widen this handler to them.
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  // The app's update check asks the network which build is live
  // (checkForUpdate in js/model/capabilities.js). The cache below matches
  // with ignoreSearch, so it would answer with the old version.js.
  if (url.searchParams.has("live")) return;

  event.respondWith(
    // caches.match without a cache name searches every cache, so an already
    // seen emoji is served from EMOJI_CACHE here.
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      // First sighting of this emoji: fetch it and keep it, so it works
      // offline from now on.
      if (url.pathname.includes(EMOJI_PATH)) {
        return fetch(req).then((res) => {
          if (res.ok) {
            const copy = res.clone();
            // waitUntil, or the worker may stop before the write lands.
            event.waitUntil(
              caches.open(EMOJI_CACHE).then((cache) => cache.put(req, copy))
            );
          }
          return res;
        });
      }
      // A navigation that missed the cache (e.g. a deep link) still gets the
      // app shell, so the installed app opens with no network. The crypto
      // prototype is deployed under our scope but is its own page: handing it
      // the app shell would make its URL silently open the editor. The same
      // holds for the test pages in /tools/ (tools/keytest.html) and for the
      // "How it works" guide in /docs/ (docs/how-it-works.html), which
      // pages.yml deploys next to the app.
      if (
        req.mode === "navigate" &&
        !url.pathname.includes("/crypto-proto") &&
        !url.pathname.includes("/tools/") &&
        !url.pathname.includes("/docs/")
      ) {
        return caches.match("./index.html").then((shell) => shell || fetch(req));
      }
      return fetch(req);
    })
  );
});
